{"code": "from hermes_tools import terminal

# Baca file sekarang
result = terminal("cat /etc/nginx/sites-available/workstation-upshalter")
content = result["output"]

# Cari posisi penutup server block SSL (sebelum "server {" HTTP block)
# Kita cari indeks baris "server {" ke-2, lalu ambil baris "}" sebelumnya
lines = content.split('\n')
ssl_end_idx = None
server_block_count = 0

for i, line in enumerate(lines):
    if line.strip() == 'server {':
        server_block_count += 1
        if server_block_count == 2:
            # Penutup block pertama ada di i-1
            ssl_end_idx = i - 1
            break

print(f"SSL server block ends at line {ssl_end_idx + 1}")
print(f"Line content: '{lines[ssl_end_idx].strip()}'")

# Blok proxy yang perlu ditambahkan
new_blocks = """

    # Archivist Agent (9124)
    location /hermes/archivist {
        proxy_pass http://127.0.0.1:9124;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }

    # Frontend Agent (9125)
    location /hermes/frontend {
        proxy_pass http://127.0.0.1:9125;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }

    # Backend Agent (9126) - NEW
    location /hermes/backend {
        proxy_pass http://127.0.0.1:9126;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }

    # VPSO Unit Upshalternal Manager (upshalter agent)
    location /hermes/VPSO {
        proxy_pass http://127.0.0.1:8645;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
    }
"""

# Insert sebelum penutup SSL block
lines.insert(ssl_end_idx, new_blocks)
new_content = '\n'.join(lines)

# Tulis kembali
with open('/etc/nginx/sites-available/workstation-upshalter', 'w') as f:
    f.write(new_content)

print("✅ Location blocks added successfully")
"}

